import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.internal.util.reflection.FieldReader;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CoreFunction_functionRound_TriageGen2Test {

    private CoreFunction coreFunction;
    private EvalContext context;
    private Expression arg1;
    private Method functionRoundMethod;

    @Before
    public void setUp() throws Exception {
        context = mock(EvalContext.class);
        arg1 = mock(Expression.class);

        // CoreFunction constructor requires functionCode and Expression array
        // Using 0 as placeholder for functionCode
        Expression[] args = new Expression[]{arg1};
        coreFunction = new CoreFunction(0, args);

        // Access protected method via reflection
        functionRoundMethod = CoreFunction.class.getDeclaredMethod("functionRound", EvalContext.class);
        functionRoundMethod.setAccessible(true);
    }

    /**
     * Helper to invoke the protected method
     */
    private Object invokeFunctionRound(EvalContext ctx) throws Exception {
        return functionRoundMethod.invoke(coreFunction, ctx);
    }

    @Test
    public void testFunctionRound_PositiveRoundUp() throws Exception {
        // Setup: Math.round(2.5) = 3
        when(arg1.computeValue(context)).thenReturn(2.5d);

        Object result = invokeFunctionRound(context);

        assertEquals(3.0, (Double) result, 0.0);
    }

    @Test
    public void testFunctionRound_PositiveRoundDown() throws Exception {
        // Setup: Math.round(2.4) = 2
        when(arg1.computeValue(context)).thenReturn(2.4d);

        Object result = invokeFunctionRound(context);

        assertEquals(2.0, (Double) result, 0.0);
    }

    @Test
    public void testFunctionRound_NegativeRoundUp() throws Exception {
        // Setup: Math.round(-2.5) = -2 (Note: Math.round rounds to positive infinity for .5 cases)
        // Math.round(-2.5) -> -2
        // Math.round(-2.51) -> -3
        when(arg1.computeValue(context)).thenReturn(-2.5d);

        Object result = invokeFunctionRound(context);

        assertEquals(-2.0, (Double) result, 0.0);
    }

    @Test
    public void testFunctionRound_NegativeRoundDown() throws Exception {
        // Setup: Math.round(-2.51) = -3
        when(arg1.computeValue(context)).thenReturn(-2.51d);

        Object result = invokeFunctionRound(context);

        assertEquals(-3.0, (Double) result, 0.0);
    }

    @Test
    public void testFunctionRound_IntegerInput() throws Exception {
        // Setup: Math.round(5.0) = 5
        when(arg1.computeValue(context)).thenReturn(5.0d);

        Object result = invokeFunctionRound(context);

        assertEquals(5.0, (Double) result, 0.0);
    }

    @Test
    public void testFunctionRound_Zero() throws Exception {
        // Setup: Math.round(0.0) = 0
        when(arg1.computeValue(context)).thenReturn(0.0d);

        Object result = invokeFunctionRound(context);

        assertEquals(0.0, (Double) result, 0.0);
    }

    @Test(expected = Exception.class)
    public void testFunctionRound_WrongArgumentCount() throws Exception {
        // To trigger assertArgCount(1) failure, we need a CoreFunction with != 1 arg.
        // Since the constructor takes args, we create one with 0 args.
        CoreFunction wrongArgFunc = new CoreFunction(0, new Expression[0]);

        // Use reflection to call the method on the wrongArgFunc
        Method method = CoreFunction.class.getDeclaredMethod("functionRound", EvalContext.class);
        method.setAccessible(true);
        method.invoke(wrongArgFunc, context);

        // Note: Depending on how assertArgCount is implemented, it might throw 
        // an IllegalArgumentException or an AssertionError. 
        // The test expects an Exception to be thrown.
    }
}
